import sys

__all__ = ["compile", "Pattern", "Match"]

# Deeply nested patterns and long backtracks must not hit the default
# recursion limit.
sys.setrecursionlimit(30000)


# ---------------------------------------------------------------------------
# Character sets
# ---------------------------------------------------------------------------

_DIGITS = frozenset(map(ord, "0123456789"))
_WORD = frozenset(map(ord,
                      "abcdefghijklmnopqrstuvwxyz"
                      "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                      "0123456789_"))
_SPACE = frozenset(map(ord, " \t\n\r\f\v"))

_SHARDS = {
    "d": _DIGITS, "D": _DIGITS,
    "w": _WORD, "W": _WORD,
    "s": _SPACE, "S": _SPACE,
}


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------

class _Node:
    __slots__ = ()


class _Lit(_Node):
    __slots__ = ("ch", "ordv")

    def __init__(self, ch):
        self.ch = ch
        self.ordv = ord(ch)


class _CharClass(_Node):
    """Matches when ``ord(ch) in include`` or ``ord(ch) not in exclude``."""

    __slots__ = ("include", "exclude")

    def __init__(self, include, exclude):
        self.include = include
        self.exclude = exclude

    def matches(self, ch):
        o = ord(ch)
        return o in self.include or o not in self.exclude


class _Dot(_Node):
    __slots__ = ()


class _AStart(_Node):
    __slots__ = ()


class _AEnd(_Node):
    __slots__ = ()


class _AWordB(_Node):
    __slots__ = ()


class _ANotWordB(_Node):
    __slots__ = ()


class _AStrStart(_Node):
    __slots__ = ()


class _AStrEnd(_Node):
    __slots__ = ()


class _Group(_Node):
    """gid 0 => non-capturing group; gid >= 1 => capture group."""

    __slots__ = ("gid", "branches")

    def __init__(self, gid, branches):
        self.gid = gid
        self.branches = branches


class _Star(_Node):
    """Quantifier: child repeated mincount..many times (greedy unless lazy)."""

    __slots__ = ("child", "min", "lazy")

    def __init__(self, child, mincount, lazy):
        self.child = child
        self.min = mincount
        self.lazy = lazy


class _Backref(_Node):
    __slots__ = ("gid",)

    def __init__(self, gid):
        self.gid = gid


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

class _Parser:
    _C_ESCAPES = {"n": "\n", "t": "\t", "r": "\r", "f": "\f", "v": "\v", "a": "\a"}

    def __init__(self, src):
        self.s = src
        self.i = 0
        self.n = len(src)
        self.ngroups = 0

    # -- low level ----------------------------------------------------------

    def peek(self, off=0):
        j = self.i + off
        return self.s[j] if j < self.n else None

    def advance(self):
        c = self.s[self.i]
        self.i += 1
        return c

    # -- entry points -------------------------------------------------------

    def parse_top(self):
        branches = [self.parse_seq()]
        while self.peek() == "|":
            self.advance()
            branches.append(self.parse_seq())
        return branches

    def parse_seq(self, stop="|"):
        seq = []
        while True:
            c = self.peek()
            if c is None or c in stop:
                return seq
            atom = self.parse_item()
            q = self.peek()
            if q in "*+?":
                self.advance()
                lazy = False
                if self.peek() == "?":
                    self.advance()
                    lazy = True
                elif self.peek() in "*+?":
                    raise ValueError("multiple repeat")
                if isinstance(atom, (_AStart, _AEnd, _AWordB, _ANotWordB,
                                     _AStrStart, _AStrEnd, _Backref)):
                    raise ValueError("nothing to repeat")
                seq.append(_Star(atom, 0 if q == "*" else 1, lazy))
            else:
                seq.append(atom)

    def parse_item(self):
        c = self.peek()
        if c == "(":
            return self.parse_group()
        if c == "[":
            return self.parse_class()
        return self.parse_atom()

    def parse_group(self):
        self.advance()  # consume '('
        c = self.peek()
        if c == "?":
            if self.peek(1) == ":":
                self.i += 2
                branches = self.parse_group_body()
                return _Group(0, branches)
            raise ValueError("unknown extension to group")
        if c == ")":
            raise ValueError("nothing to repeat (empty group)")
        self.ngroups += 1
        gid = self.ngroups
        branches = self.parse_group_body()
        return _Group(gid, branches)

    def parse_group_body(self):
        branches = [self.parse_seq(stop="|)")]
        while self.peek() == "|":
            self.advance()
            branches.append(self.parse_seq(stop="|)"))
        if self.peek() != ")":
            raise ValueError("missing )")
        self.advance()
        return branches

    def parse_atom(self):
        c = self.advance()
        if c == ".":
            return _Dot()
        if c == "^":
            return _AStart()
        if c == "$":
            return _AEnd()
        if c == "\\":
            return self.parse_escape()
        return _Lit(c)

    # -- escapes ------------------------------------------------------------

    def parse_escape(self):
        c = self.peek()
        if c is None:
            raise ValueError("incomplete escape")
        self.advance()
        if c in self._C_ESCAPES:
            return _Lit(self._C_ESCAPES[c])
        if c == "0":
            return _Lit(self.octal_char())
        if "1" <= c <= "9":
            d = c
            while self.peek() is not None and "0" <= self.peek() <= "9":
                d += self.advance()
            return _Backref(int(d))
        if c == "b":
            return _AWordB()
        if c == "B":
            return _ANotWordB()
        if c == "A":
            return _AStrStart()
        if c in "Zz":
            return _AStrEnd()
        if c in _SHARDS:
            return self.shard_class(c)
        if c == "u":
            return _Lit(self.hex_char(4))
        if c == "U":
            return _Lit(self.hex_char(8))
        if c == "x":
            return _Lit(self.hex_char(2))
        if c == "c":
            d = self.advance()
            if d is None or not (32 <= ord(d) <= 126):
                raise ValueError("bad escape \\c")
            return _Lit(chr(ord(d) & 31))
        if c.isalpha():
            raise ValueError("bad escape \\\\%s" % c)
        return _Lit(c)

    def octal_char(self):
        """'0' already consumed; read up to two more octal digits."""
        d = "0"
        for _ in range(2):
            p = self.peek()
            if p is not None and "0" <= p <= "7":
                d += self.advance()
            else:
                break
        v = int(d, 8)
        if v > 255:
            raise ValueError("octal escape exceeds 0o377")
        return chr(v)

    def hex_char(self, k):
        d = ""
        for _ in range(k):
            p = self.peek()
            if p is not None and p in "0123456789abcdefABCDEF":
                d += self.advance()
            else:
                raise ValueError("incomplete hex escape")
        v = int(d, 16)
        if v > 0x10FFFF:
            raise ValueError("unicode overflow")
        return chr(v)

    def shard_class(self, c):
        s = _SHARDS[c]
        if c.isupper():
            return _CharClass(frozenset(), s)
        return _CharClass(s, frozenset())

    def class_escape_char(self, c):
        """Resolve a backslashed *single character* inside a class."""
        if c in self._C_ESCAPES:
            return self._C_ESCAPES[c]
        if c == "b":
            return "\x08"
        if c == "0":
            return self.octal_char()
        if "1" <= c <= "7":
            d = c
            for _ in range(2):
                p = self.peek()
                if p is not None and "0" <= p <= "7":
                    d += self.advance()
                else:
                    break
            return chr(int(d, 8))
        if c in "89":
            return c
        if c == "u":
            return self.hex_char(4)
        if c == "U":
            return self.hex_char(8)
        if c == "x":
            return self.hex_char(2)
        if c.isalpha():
            raise ValueError("bad escape \\\\%s" % c)
        return c

    # -- character classes ----------------------------------------------------

    def parse_class(self):
        self.advance()  # consume '['
        neg = False
        if self.peek() == "^":
            neg = True
            self.advance()
        include = set()
        exclude = set()
        first = True
        while True:
            c = self.peek()
            if c is None:
                raise ValueError("unterminated character set")
            if c == "]":
                if first:
                    (exclude if neg else include).add(ord("]"))
                    self.advance()
                    first = False
                    continue
                self.advance()
                break
            first = False
            left = None
            if c == "\\":
                self.advance()
                e = self.advance()
                if e is None:
                    raise ValueError("unterminated character set")
                if e in _SHARDS:
                    s = _SHARDS[e]
                    if neg or e.isupper():
                        exclude.update(s)
                    else:
                        include.update(s)
                    continue
                left = self.class_escape_char(e)
            elif c == "-":
                left = "-"
                self.advance()
            else:
                left = c
                self.advance()
            if self.peek() == "-" and self.peek(1) not in ("]", None):
                self.advance()  # consume '-'
                r = self.peek()
                if r == "\\":
                    self.advance()
                    e = self.advance()
                    if e is None:
                        raise ValueError("unterminated character set")
                    if e in _SHARDS:
                        raise ValueError("bad character range")
                    right = self.class_escape_char(e)
                else:
                    right = self.advance()
                lo, hi = ord(left), ord(right)
                if hi < lo:
                    raise ValueError("bad character range")
                tgt = exclude if neg else include
                tgt.update(range(lo, hi + 1))
            else:
                (exclude if neg else include).add(ord(left))
        return _CharClass(frozenset(include), frozenset(exclude))


def _validate_node(nd, ngroups):
    t = type(nd)
    if t is _Backref:
        if nd.gid > ngroups:
            raise ValueError("invalid group reference %d" % nd.gid)
    elif t is _Star:
        _validate_node(nd.child, ngroups)
    elif t is _Group:
        for br in nd.branches:
            for child in br:
                _validate_node(child, ngroups)


# ---------------------------------------------------------------------------
# Matcher
# ---------------------------------------------------------------------------

def _word_boundary(text, pos):
    L = len(text)
    prevw = pos > 0 and ord(text[pos - 1]) in _WORD
    nextw = pos < L and ord(text[pos]) in _WORD
    return prevw != nextw


def _node(pat, nd, text, pos, caps):
    """Match one AST node at ``pos``.  Return (new_pos, new_caps) or None."""
    t = type(nd)
    if t is _Lit:
        if pos < len(text) and text[pos] == nd.ch:
            return pos + 1, caps
        return None
    if t is _Dot:
        if pos < len(text) and text[pos] != "\n":
            return pos + 1, caps
        return None
    if t is _CharClass:
        if pos < len(text) and nd.matches(text[pos]):
            return pos + 1, caps
        return None
    L = len(text)
    if t is _AStart or t is _AStrStart:
        return (0, caps) if pos == 0 else None
    if t is _AEnd:
        if pos == L or (pos == L - 1 and text[pos] == "\n"):
            return pos, caps
        return None
    if t is _AStrEnd:
        return (pos, caps) if pos == L else None
    if t is _AWordB:
        return (pos, caps) if _word_boundary(text, pos) else None
    if t is _ANotWordB:
        return (pos, caps) if not _word_boundary(text, pos) else None
    if t is _Group:
        gid = nd.gid
        caps2 = caps
        if gid:
            caps2 = caps[:gid] + (None,) + caps[gid + 1:]
        for br in nd.branches:
            r = _seq(pat, br, 0, text, pos, caps2)
            if r is not None:
                np, nc = r
                if gid:
                    nc = nc[:gid] + ((pos, np),) + nc[gid + 1:]
                return np, nc
        return None
    if t is _Backref:
        span = caps[nd.gid]
        if span is None:
            return None
        s, e = span
        m = e - s
        if pos + m <= L and text[pos:pos + m] == text[s:e]:
            return pos + m, caps
        return None
    return None


def _seq(pat, nodes, i, text, pos, caps):
    """Match nodes[i:] at ``pos``.  Return (end_pos, caps) or None."""
    L = len(nodes)
    while i < L:
        nd = nodes[i]
        if type(nd) is _Star:
            cands = [(pos, caps)]
            p = pos
            c = caps
            child = nd.child
            while True:
                r = _node(pat, child, text, p, c)
                if r is None:
                    break
                np, nc = r
                if np == p:
                    # Zero-width child success: do not repeat forever.  For
                    # ``+`` a single zero-width iteration still satisfies
                    # the quantifier.
                    if nd.min:
                        cands.append((np, nc))
                    break
                p, c = np, nc
                cands.append((p, c))
            if nd.lazy:
                rng = range(nd.min, len(cands))
            else:
                rng = range(len(cands) - 1, nd.min - 1, -1)
            for k in rng:
                cp, cc = cands[k]
                r = pat._seq(nodes, i + 1, text, cp, cc)
                if r is not None:
                    return r
            return None
        r = _node(pat, nd, text, pos, caps)
        if r is None:
            return None
        pos, caps = r
        i += 1
    return pos, caps


def _branch_first(b):
    if not b:
        return "any"
    n0 = b[0]
    t = type(n0)
    if t is _Lit:
        return ("char", n0.ordv)
    if t is _CharClass:
        return ("cls", n0)
    if t is _Dot:
        return ("dot", None)
    return "any"


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

class Pattern:
    """Compiled regex pattern.  Returned by ``compile()``."""

    __slots__ = ("_src", "_branches", "_ngroups", "_caps0",
                 "_firstinfos", "_pos0_only")

    def __init__(self, src, branches, ngroups):
        self._src = src
        self._branches = branches
        self._ngroups = ngroups
        self._caps0 = (None,) * (ngroups + 1)
        self._firstinfos = [_branch_first(b) for b in branches]
        self._pos0_only = bool(branches) and all(
            b and isinstance(b[0], (_AStart, _AStrStart)) for b in branches)

    # -- helpers -------------------------------------------------------------

    def _seq(self, nodes, i, text, pos, caps):
        return _seq(self, nodes, i, text, pos, caps)

    @staticmethod
    def _pos_ok(infos, text, pos):
        n = len(text)
        for inf in infos:
            if isinstance(inf, str):
                return True
            if pos >= n:
                continue
            ch = text[pos]
            kind, payload = inf
            if kind == "char":
                if ord(ch) == payload:
                    return True
            elif kind == "cls":
                if payload.matches(ch):
                    return True
            else:  # dot
                if ch != "\n":
                    return True
        return False

    def _search_from(self, text, start):
        n = len(text)
        if start > n:
            return None
        if self._pos0_only:
            if start > 0:
                return None
            positions = (0,)
        else:
            positions = range(start, n + 1)
        infos = self._firstinfos
        for pos in positions:
            if not self._pos_ok(infos, text, pos):
                continue
            caps = self._caps0
            for br in self._branches:
                r = _seq(self, br, 0, text, pos, caps)
                if r is not None:
                    end, caps = r
                    return Match(text, pos, end, caps)
        return None

    # -- public API ----------------------------------------------------------

    def fullmatch(self, text: str):
        """Return a Match if ``pattern`` matches the entire ``text``,
        else None.
        """
        if not isinstance(text, str):
            raise TypeError("fullmatch() expects a string")
        if not self._pos_ok(self._firstinfos, text, 0):
            return None
        caps = self._caps0
        L = len(text)
        for br in self._branches:
            r = _seq(self, br, 0, text, 0, caps)
            if r is not None and r[0] == L:
                return Match(text, 0, L, r[1])
        return None

    def search(self, text: str):
        """Return a Match for the first occurrence of ``pattern`` in
        ``text``, else None.
        """
        if not isinstance(text, str):
            raise TypeError("search() expects a string")
        return self._search_from(text, 0)

    def findall(self, text: str) -> list:
        """Return a list of all non-overlapping match strings."""
        if not isinstance(text, str):
            raise TypeError("findall() expects a string")
        out = []
        pos = 0
        n = len(text)
        while pos <= n:
            m = self._search_from(text, pos)
            if m is None:
                break
            out.append(text[m._start:m._end])
            pos = m._end + 1 if m._end == m._start else m._end
        return out


class Match:
    """Match result.  Returned by Pattern.fullmatch / Pattern.search."""

    __slots__ = ("_text", "_start", "_end", "_caps")

    def __init__(self, text, start, end, caps):
        self._text = text
        self._start = start
        self._end = end
        self._caps = caps

    def group(self, n: int = 0) -> str:
        """Return the n-th capture group.  ``n=0`` is the whole match.
        ``n>=1`` indexes capture groups left-to-right by their opening
        paren.  Return ``None`` if the group did not participate in the
        match.
        """
        if not isinstance(n, int) or isinstance(n, bool):
            raise TypeError("group() expects an int")
        if n == 0:
            return self._text[self._start:self._end]
        if 1 <= n < len(self._caps):
            span = self._caps[n]
            if span is None:
                return None
            s, e = span
            return self._text[s:e]
        raise IndexError("no such group: %d" % n)

    def start(self) -> int:
        """Index into the input text where the match starts."""
        return self._start

    def end(self) -> int:
        """Index into the input text where the match ends (exclusive)."""
        return self._end

    def span(self) -> tuple:
        """``(start, end)`` of the match."""
        return (self._start, self._end)


def compile(pattern: str) -> Pattern:
    """Parse and compile ``pattern`` into a Pattern object.

    Raise ``ValueError`` on syntactic errors (unbalanced parens,
    dangling quantifier, etc.).
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    p = _Parser(pattern)
    branches = p.parse_top()
    ngroups = p.ngroups
    for br in branches:
        for nd in br:
            _validate_node(nd, ngroups)
    return Pattern(pattern, branches, ngroups)
