    # -- character classes ----------------------------------------------------

    def parse_class(self):
        self.advance()  # consume '['
        neg = False
        if self.peek() == "^":
            neg = True
            self.advance()
        include = set()
        exclude = set()
        first = True
        while True:
            c = self.peek()
            if c is None:
                raise ValueError("unterminated character set")
            if c == "]":
                if first:
                    (exclude if neg else include).add(ord("]"))
                    self.advance()
                    first = False
                    continue
                self.advance()
                break
            first = False
            left = None
            if c == "\\":
                self.advance()
                e = self.advance()
                if e is None:
                    raise ValueError("unterminated character set")
                if e in _SHARDS:
                    s = _SHARDS[e]
                    if neg or e.isupper():
                        exclude.update(s)
                    else:
                        include.update(s)
                    continue
                left = self.class_escape_char(e)
            elif c == "-":
                left = "-"
                self.advance()
            else:
                left = c
                self.advance()
            if self.peek() == "-" and self.peek(1) not in ("]", None):
                self.advance()  # consume '-'
                r = self.peek()
                if r == "\\":
                    self.advance()
                    e = self.advance()
                    if e is None:
                        raise ValueError("unterminated character set")
                    if e in _SHARDS:
                        raise ValueError("bad character range")
                    right = self.class_escape_char(e)
                else:
                    right = self.advance()
                lo, hi = ord(left), ord(right)
                if hi < lo:
                    raise ValueError("bad character range")
                tgt = exclude if neg else include
                tgt.update(range(lo, hi + 1))
