        return None
    return None


def _seq(pat, nodes, i, text, pos, caps):
    """Match nodes[i:] at ``pos``.  Return (end_pos, caps) or None."""
    L = len(nodes)
    while i < L:
        nd = nodes[i]
        if type(nd) is _Star:
            cands = [(pos, caps)]
            p = pos
            c = caps
            child = nd.child
            while True:
                r = _node(pat, child, text, p, c)
                if r is None:
                    break
