                p, c = np, nc
                cands.append((p, c))
            if nd.lazy:
                rng = range(nd.min, len(cands))
            else:
                rng = range(len(cands) - 1, nd.min - 1, -1)
            for k in rng:
                cp, cc = cands[k]
                r = pat._seq(nodes, i + 1, text, cp, cc)
                if r is not None:
                    return r
            return None
        r = _node(pat, nd, text, pos, caps)
        if r is None:
            return None
        pos, caps = r
        i += 1
    return pos, caps


