    if not b:
        return "any"
    n0 = b[0]
    t = type(n0)
    if t is _Lit:
        return ("char", n0.ordv)
    if t is _CharClass:
        return ("cls", n0)
    if t is _Dot:
        return ("dot", None)
    return "any"


