        L = len(text)
        for br in self._branches:
            r = _seq(self, br, 0, text, 0, caps)
            if r is not None and r[0] == L:
                return Match(text, 0, L, r[1])
        return None

    def search(self, text: str):
        """Return a Match for the first occurrence of ``pattern`` in
        ``text``, else None.
        """
        if not isinstance(text, str):
            raise TypeError("search() expects a string")
        return self._search_from(text, 0)

    def findall(self, text: str) -> list:
        """Return a list of all non-overlapping match strings."""
        if not isinstance(text, str):
            raise TypeError("findall() expects a string")
        out = []
        pos = 0
        n = len(text)
        while pos <= n:
            m = self._search_from(text, pos)
            if m is None:
